func init() {
    runtime.RegisterStorageBackend(func(
        ctx context.Context,
        logger logging.Logger,
        registerer prometheus.Registerer,
        config []byte,
        id string,
    ) (storage.Store, error) {
        return myCustomStore, nil
    })
}

